import XCTest
@testable import OpenPatchCore

/// Byte for byte parity with the Rust pod (`firmware-rs`): `docs/vectors/wire-v1-scenarios.json` holds the frames of a REAL cup
/// pod (generated by `firmware-rs/openpatch-core/tests/wire_vectors.rs`) driven through the whole bench flow.
///
/// * Every request the Swift transport would send for the same domain command must equal the Rust encoder's frame, byte for byte.
/// * Every response of the pod must decode, and every field of its status must come out right.
final class WireGoldenTests: XCTestCase {
    /// Never carries anything: only the planning and decoding functions of the transport are exercised.
    private final class IdleLink: FrameLink {
        var isConnected = true
        func connect(completion: @escaping (Result<Void, TransportError>) -> Void) { completion(.success(())) }
        func disconnect() {}
        func exchange(frame: Data, seq: UInt16, completion: @escaping (Result<Data, TransportError>) -> Void) { completion(.failure(.timeout)) }
    }

    private func loadScenarios() throws -> (timeOfDay: UInt32, scenarios: [[String: Any]]) {
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<6 { url.deleteLastPathComponent() }
        let data = try Data(contentsOf: url.appendingPathComponent("docs/vectors/wire-v1-scenarios.json"))
        let root = try JSONSerialization.jsonObject(with: data) as! [String: Any]
        return (UInt32(root["time_of_day_ms"] as! Int), root["scenarios"] as! [[String: Any]])
    }

    private func bytes(_ hex: String) -> [UInt8] {
        var out: [UInt8] = []
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            out.append(UInt8(hex[index..<next], radix: 16)!)
            index = next
        }
        return out
    }

    private func program(_ segments: [(hours: Double, rate: Double)]) throws -> BasalProgram {
        try BasalProgram(segments: segments.map { BasalSegment(startOffset: $0.hours * 3600, unitsPerHour: $0.rate) })
    }

    private let pair: UInt32 = 0xCAFE_0001

    /// The domain command the phone sends for a golden step; `nil` = the Rust test sends something the app never sends
    /// (a refused amount that is not a multiple of 0.05 U, an unknown sub-op): decode only.
    private func command(for name: String) throws -> Command? {
        if name.hasPrefix("get_status") || name == "replayed_get_status_is_dropped" { return .getStatus }
        if name.hasPrefix("prime_71_steps") { return .prime }
        switch name {
        case "set_pairing": return .setPairing(pairID: pair, role: .a)
        case "assisted_fill_20u": return .assistedFill(pulses: 400)
        case "assisted_fill_30u": return .assistedFill(pulses: 600)
        case "assisted_fill_busy", "assisted_fill_while_running", "assisted_fill_while_docked": return .assistedFill(pulses: 20)
        case "assisted_fill_cancel_without_draw", "assisted_fill_cancel": return .cancelAssistedFill
        case "activate":
            return .activatePod(pairID: pair, activationID: 7, program: try program([(0, 0.8), (6, 1.25), (18, 0.6)]), tempBasal: nil)
        case "set_basal_schedule": return .setBasalProgram(try program([(0, 0.8), (6, 1.25)]))
        case "resume": return .resume
        case "suspend": return .suspend
        case "bolus_smb_0_05u", "bolus_while_suspended", "bolus_after_release": return .bolus(id: 1, pulses: 1)
        case "bolus_2u": return .bolus(id: 2, pulses: 40)
        case "bolus_above_hard_limit": return .bolus(id: 3, pulses: 600)
        case "cancel_bolus", "cancel_bolus_none_running": return .cancelBolus
        case "set_temp_basal_1_5uph_30min": return .setTempBasal(rateTicks: 30, durationMinutes: 30)
        case "cancel_temp_basal": return .cancelTempBasal
        case "acknowledge_all": return .silenceAlarm
        case "release": return .releasePod(pairID: pair)
        default: return nil
        }
    }

    private func firstStatusMessage(_ scenarios: [[String: Any]]) throws -> V1.Message {
        let steps = scenarios[0]["steps"] as! [[String: Any]]
        let first = try XCTUnwrap(steps.first { $0["name"] as? String == "get_status_fresh" })
        return try V1.decode(Data(bytes((first["response"] as! [String: Any])["wire"] as! String)))
    }

    private func status(_ value: Any?) -> [String: Int]? { (value as? [String: Any])?.mapValues { $0 as! Int } }

    func testEveryRequestOfTheScenarioIsReproducedByteForByte() throws {
        let (timeOfDay, scenarios) = try loadScenarios()
        var compared = 0, decodeOnly = 0
        for scenario in scenarios {
            let transport = V1Transport(link: IdleLink(), initialPhase: .paired)
            _ = transport.parseStatus(try firstStatusMessage(scenarios))   // the app reads the status when it connects: learns DRIVE_CAL
            for step in scenario["steps"] as! [[String: Any]] {
                let name = step["name"] as! String
                let request = step["request"] as! [String: Any]
                let wire = bytes(request["wire"] as! String)
                if let response = step["response"] as? [String: Any], let st = status(response["status"]), !st.isEmpty {
                    _ = transport.parseStatus(try V1.decode(Data(bytes(response["wire"] as! String))))   // learns DRIVE_CAL like the app does
                }
                guard let command = try command(for: name) else {
                    // still: the frame itself must be a valid v1 frame
                    XCTAssertNoThrow(try V1.decode(Data(wire)), name)
                    decodeOnly += 1
                    continue
                }
                let seq = UInt16(request["seq"] as! Int)
                let wireRequest = try XCTUnwrap(transport.wireRequest(for: command), name)
                let frame = V1.encode(V1.Message(type: wireRequest.id.rawValue, seq: seq,
                                                 tlvs: [V1.TLV(.timeOfDayMS, u32: timeOfDay)] + wireRequest.tlvs))
                XCTAssertEqual([UInt8](frame), wire, "\(scenario["name"] as! String) / \(name)")
                XCTAssertEqual(wireRequest.id.rawValue, UInt8(request["type"] as! Int), name)
                compared += 1
            }
        }
        XCTAssertEqual(compared, 40)
        // 2 raw-amount refusals + the unknown sub-op (the app never sends them) + 2 history pages (own test below)
        XCTAssertEqual(decodeOnly, 5)
    }

    func testHistoryRequestsMatchTheRustEncoder() throws {
        let (timeOfDay, scenarios) = try loadScenarios()
        let steps = (scenarios[0]["steps"] as! [[String: Any]])
        for (name, cursor) in [("get_history_all", UInt32(0)), ("get_history_page_2", UInt32(10))] {
            let step = try XCTUnwrap(steps.first { $0["name"] as? String == name })
            let request = step["request"] as! [String: Any]
            let frame = V1.encode(V1.Message(type: V1.CommandID.getHistory.rawValue, seq: UInt16(request["seq"] as! Int),
                                             tlvs: [V1.TLV(.timeOfDayMS, u32: timeOfDay)] + V1Transport.historyTLVs(from: cursor)))
            XCTAssertEqual([UInt8](frame), bytes(request["wire"] as! String), name)
        }
    }

    func testEveryResponseOfThePodDecodesWithAllItsFields() throws {
        let (_, scenarios) = try loadScenarios()
        var statuses = 0, results = Set<Int>()
        for scenario in scenarios {
            let transport = V1Transport(link: IdleLink(), initialPhase: .paired)
            for step in scenario["steps"] as! [[String: Any]] {
                guard let response = step["response"] as? [String: Any] else { continue }
                let name = step["name"] as! String
                let message = try V1.decode(Data(bytes(response["wire"] as! String)))
                XCTAssertTrue(message.isResponse, name)
                XCTAssertEqual(message.type, UInt8(response["type"] as! Int), name)
                XCTAssertEqual(message.seq, UInt16(response["seq"] as! Int), name)
                let code = response["result"] as! Int
                results.insert(code)
                XCTAssertEqual(message.result?.rawValue, UInt8(code), "\(name): Swift does not know result code \(code)")
                guard let st = status(response["status"]), !st.isEmpty else { continue }
                statuses += 1
                func u(_ tag: V1.Tag, _ key: String, width: Int, line: UInt = #line) {
                    let have: Int? = width == 2 ? message.u16(tag).map(Int.init) : (width == 4 ? message.u32(tag).map(Int.init) : message.u8(tag).map(Int.init))
                    XCTAssertEqual(have, st[key], "\(name): \(key)", line: line)
                }
                u(.stateFlags, "flags", width: 2); u(.faultMask, "faults", width: 2); u(.batteryMV, "battery_mv", width: 2)
                u(.tempRateMUh, "temp_rate_mu_h", width: 2); u(.tempRemainingMin, "temp_remaining_min", width: 2)
                u(.currentRateMUh, "current_rate_mu_h", width: 2); u(.fwVersion, "fw_version", width: 2)
                u(.reservoirMU, "reservoir_mu", width: 4); u(.bolusRemainingMU, "bolus_remaining_mu", width: 4)
                u(.deliveredMU, "delivered_mu", width: 4); u(.scheduledMU, "scheduled_mu", width: 4)
                u(.nextEventID, "next_event_id", width: 4); u(.lastSeq, "last_seq", width: 2)
                u(.drawState, "draw_state", width: 1); u(.drawRequestedMU, "draw_requested_mu", width: 4); u(.drawDoneMU, "draw_done_mu", width: 4)

                let parsed = transport.parseStatus(message)
                let calibration = try XCTUnwrap(parsed.driveCalibration, name)
                XCTAssertEqual(calibration.driveID, UInt16(st["cal_drive_id"]!), name)
                XCTAssertEqual(calibration.microUnitsPerStep, UInt32(st["cal_uu_per_step"]!), name)
                XCTAssertEqual(calibration.stepsPerRevolution, UInt16(st["cal_steps_per_rev"]!), name)
                XCTAssertEqual(calibration.gearRatioTimes100, UInt16(st["cal_gear_ratio_x100"]!), name)
                XCTAssertEqual(calibration, .nfp608_26_45_cupMiter1_1, "\(name): the cup pod's DRIVE_CAL is a known drive")
                XCTAssertEqual(Int(parsed.reservoirPulses), st["reservoir_mu"]! / 50, name)
                XCTAssertEqual(Int(parsed.totalDeliveredPulses), st["delivered_mu"]! / 50, name)
                let fill = try XCTUnwrap(parsed.fill, "\(name): the cup pod reports its fill state")
                XCTAssertEqual(fill.state.rawValue, UInt8(st["draw_state"]!), name)
                XCTAssertEqual(fill.requestedUnits, Double(st["draw_requested_mu"]!) / 1000, name)
                XCTAssertEqual(fill.drawnUnits, Double(st["draw_done_mu"]!) / 1000, name)
                XCTAssertEqual(fill.primeRequired, st["flags"]! & Int(V1.StateFlags.primeRequired.rawValue) != 0, name)
                XCTAssertEqual(fill.isRunning, st["flags"]! & Int(V1.StateFlags.drawing.rawValue) != 0, name)
                XCTAssertEqual(message.value(.podInfo)?.count, 10, name)
                XCTAssertEqual(parsed.pairing?.pairID, UInt32(st["pair_id"]!), name)
                XCTAssertEqual(parsed.pairing?.wearSeconds, UInt32(st["wear_s"]!), name)
            }
        }
        XCTAssertGreaterThan(statuses, 12)
        // every refusal code the cup flow produces is one Swift knows: busy, limit, bad arg, not found, not suspended,
        // suspended, prime/hourly, docked (27, Rust extension), released
        for code in [0, 1, 2, 3, 5, 6, 16, 17, 20, 27] { XCTAssertTrue(results.contains(code), "scenario never produced result \(code)") }
    }

    func testHistoryResponsesDecodeToTheRustEvents() throws {
        let (_, scenarios) = try loadScenarios()
        let steps = scenarios[0]["steps"] as! [[String: Any]]
        var haveEvents: [V1.HistoryEvent] = [], want: [[String: Any]] = []
        for name in ["get_history_all", "get_history_page_2"] {
            let step = try XCTUnwrap(steps.first { $0["name"] as? String == name })
            let response = step["response"] as! [String: Any]
            let history = response["history"] as! [String: Any]
            let message = try V1.decode(Data(bytes(response["wire"] as! String)))
            let page = history["events"] as! [[String: Any]]
            XCTAssertEqual(message.historyEvents.count, page.count)
            XCTAssertEqual(message.u32(.nextEventID), UInt32(history["next_event_id"] as! Int))
            haveEvents += message.historyEvents
            want += page
        }
        for (have, expected) in zip(haveEvents, want) {
            XCTAssertEqual(Int(have.id), expected["id"] as! Int)
            XCTAssertEqual(Int(have.type), expected["kind"] as! Int)
            XCTAssertEqual(Int(have.a), expected["a"] as! Int)
            XCTAssertEqual(Int(have.b), expected["b"] as! Int)
            XCTAssertNotNil(V1.HistoryType(rawValue: have.type), "event kind \(have.type) unknown to Swift")
        }
        // the bolus events map to the domain: start (0.05 U = 1 pulse) is the proof of execution after a lost reply
        let transport = V1Transport(link: IdleLink(), initialPhase: .active)
        let starts = haveEvents.filter { $0.type == V1.HistoryType.bolusStart.rawValue }
        XCTAssertFalse(starts.isEmpty)
        XCTAssertEqual(transport.domainEvent(for: starts[0]), .bolusStarted(pulses: UInt16(starts[0].a / 50)))
        let temps = haveEvents.filter { $0.type == V1.HistoryType.tempStart.rawValue }
        if let temp = temps.first {
            XCTAssertEqual(transport.domainEvent(for: temp), .tempBasalStarted(rateTicks: UInt16(temp.a / 50), durationMinutes: UInt16(temp.b)))
        }
    }

    func testTheFillOfTheCupPodIsReadAsSuchByThePhone() throws {
        let (_, scenarios) = try loadScenarios()
        func status(_ scenario: Int, _ name: String) throws -> PodStatus {
            let steps = scenarios[scenario]["steps"] as! [[String: Any]]
            let step = try XCTUnwrap(steps.first { $0["name"] as? String == name }, name)
            let message = try V1.decode(Data(bytes((step["response"] as! [String: Any])["wire"] as! String)))
            return V1Transport(link: IdleLink(), initialPhase: .paired).parseStatus(message)
        }
        let drawing = try status(0, "get_status_drawing")
        XCTAssertEqual(drawing.fill?.state, .drawing)
        XCTAssertEqual(drawing.fill?.requestedUnits, 20.0)
        let done = try status(0, "get_status_draw_done")
        XCTAssertEqual(done.fill?.state, .done)
        XCTAssertEqual(try XCTUnwrap(done.fill).drawnUnits, 19.994, accuracy: 0.0005, "step exact: a whole number of 7.03 mU steps")
        XCTAssertTrue(try XCTUnwrap(done.fill).primeRequired)
        XCTAssertEqual(done.reservoirUnits, 19.95, accuracy: 0.051, "whole 0.05 U pulses")
        let aborted = try status(1, "get_status_aborted")
        XCTAssertEqual(aborted.fill?.state, .aborted)
        XCTAssertGreaterThan(try XCTUnwrap(aborted.fill).drawnUnits, 0, "what was drawn before the cancel stays booked")
        let stalled = try status(1, "get_status_stalled")
        XCTAssertEqual(stalled.fill?.state, .stalled)
        XCTAssertLessThan(try XCTUnwrap(stalled.fill).drawnUnits, 30)
        // the prime answers `Hourly` once (take-up of the drive's lost motion), and the phone sees it as such
        let steps = scenarios[0]["steps"] as! [[String: Any]]
        let first = try XCTUnwrap(steps.first { $0["name"] as? String == "prime_71_steps_try_1" })
        let message = try V1.decode(Data(bytes((first["response"] as! [String: Any])["wire"] as! String)))
        XCTAssertEqual(message.result, .hourly)
        XCTAssertEqual(V1Transport.nack(for: .hourly, command: .prime), .hourlyLimit)
    }

    func testRefusalsOfTheCupFlowMapToNackReasons() {
        XCTAssertEqual(V1Transport.nack(for: .docked, command: .assistedFill(pulses: 20)), .podDocked)
        XCTAssertEqual(V1Transport.nack(for: .primeRequired, command: .resume), .primeRequired)
        XCTAssertEqual(V1Transport.nack(for: .notSuspended, command: .assistedFill(pulses: 20)), .invalidState)
        XCTAssertNil(V1Transport.nack(for: .notFound, command: .cancelBolus), "cancelling nothing is already the desired end state")
        XCTAssertEqual(V1Transport.nack(for: .notFound, command: .cancelAssistedFill), .invalidState)
        XCTAssertEqual(V1Transport.nack(for: .limit, command: .assistedFill(pulses: 5000)), .limitExceeded)
    }
}
